// End-to-end check of `frai setup` / `frai config` / frai-agent key resolution in temp dirs.
import { spawnSync } from 'child_process';
import fs from 'fs';
import os from 'os';
import path from 'path';

const REPO = '/private/tmp/100-tricks-runs/pilot-hard/without/h3-key-store/r2';
const CLI = path.join(REPO, 'packages/frai-cli/dist/index.js');
const AGENT_ENV = path.join(REPO, 'packages/frai-agent/dist/config/env.js');

const tmp = fs.mkdtempSync(path.join(os.tmpdir(), 'frai-e2e-'));
const home = path.join(tmp, 'home');
const proj = path.join(tmp, 'proj');
const configPath = path.join(home, '.config/frai/config');
fs.mkdirSync(path.dirname(configPath), { recursive: true });
fs.mkdirSync(proj);

const env = { ...process.env, HOME: home };
delete env.OPENAI_API_KEY;

const run = (label, args) => {
  const r = spawnSync(process.execPath, [CLI, ...args], { cwd: proj, env, input: '', timeout: 10000, encoding: 'utf8' });
  console.log(`\n== ${label}: frai ${args.join(' ')} (exit=${r.status}${r.signal ? ` signal=${r.signal}` : ''})`);
  process.stdout.write((r.stdout + r.stderr).replace(/^\[[^\]]+\] /gm, ''));
};
const show = (file) => console.log(`--- ${path.basename(file)} ---\n${JSON.stringify(fs.readFileSync(file, 'utf8'))}`);
const envFile = path.join(proj, '.env');

fs.writeFileSync(envFile, '# project\n\nFOO=bar\nexport OPENAI_API_KEY="sk-old" # rotated\nZ=1\n');
fs.writeFileSync(configPath, '{\n  "theme": "dark"\n}');

run('config, export+quoted+comment key', ['config']);
const agent = spawnSync(
  process.execPath,
  ['-e', `import(${JSON.stringify(AGENT_ENV)}).then(m => console.log('agent key:', m.resolveOpenAiApiKey({ root: ${JSON.stringify(proj)} })))`],
  { cwd: path.join(REPO, 'packages/frai-agent'), env, encoding: 'utf8' }
);
console.log('\n== frai-agent', agent.stdout + agent.stderr);

run('local', ['setup', '--key', 'sk-local']);
show(envFile);
run('global', ['setup', '--key', 'sk-global', '--global']);
show(configPath);
show(envFile);
run('legacy local', ['--setup', '--key', 'sk-legacy']);
show(envFile);
run('legacy global', ['--setup', '--key', 'sk-legacy-global', '--global']);
show(configPath);

fs.writeFileSync(configPath, '{ broken');
run('invalid global json', ['setup', '--key', 'sk-x', '--global']);
show(configPath);

fs.writeFileSync(envFile, 'FOO=bar\n# OPENAI_API_KEY=sk-commented\n');
fs.writeFileSync(configPath, '{"theme":"dark","OPENAI_API_KEY":""}');
run('config, no usable keys', ['config']);

fs.rmSync(tmp, { recursive: true, force: true });

